import itertools
from pysat.solvers import Glucose3
from pysat.card import CardEnc

def solve():
    num_vertices = 15
    fixed_edges = {(2, 12), (3, 10), (6, 9), (3, 13), (3, 12), (0, 13)}

    all_possible_edges = []
    for u in range(num_vertices):
        for v in range(u + 1, num_vertices):
            all_possible_edges.append((u, v))

    solver = Glucose3()

    edge_to_var = {}
    var_to_edge = {}
    var_count = 1
    for u, v in all_possible_edges:
        edge_to_var[(u, v)] = var_count
        var_to_edge[var_count] = (u, v)
        var_count += 1

    for edge in fixed_edges:
        solver.add_clause([edge_to_var[tuple(sorted(edge))]])

    for triplet in itertools.combinations(range(num_vertices), 3):
        u, v, w = triplet
        e1 = tuple(sorted((u, v)))
        e2 = tuple(sorted((v, w)))
        e3 = tuple(sorted((u, w)))
        solver.add_clause([-edge_to_var[e1], -edge_to_var[e2], -edge_to_var[e3]])

    # Use a vpool for cardinality constraints
    from pysat.card import IDPool
    vpool = IDPool(start_from=var_count)

    for v in range(num_vertices):
        incident_edges = []
        for u in range(num_vertices):
            if u == v: continue
            edge = tuple(sorted((u, v)))
            incident_edges.append(edge_to_var[edge])

        # At least 2
        clauses = CardEnc.atleast(lits=incident_edges, bound=2, vpool=vpool)
        for c in clauses:
            solver.add_clause(c)

        # At most 5
        clauses = CardEnc.atmost(lits=incident_edges, bound=5, vpool=vpool)
        for c in clauses:
            solver.add_clause(c)

    if solver.solve():
        model = solver.get_model()
        result_edges = []
        for var in model:
            if var > 0 and var in var_to_edge:
                result_edges.append(var_to_edge[var])
        return result_edges
    else:
        return None

result = solve()
print(result)

import networkx as nx

def check_solution(edges, num_vertices=15):
    G = nx.Graph()
    G.add_nodes_from(range(num_vertices))
    G.add_edges_from(edges)

    # Check girth >= 4
    try:
        cycle = nx.find_cycle(G, orientation="original")
        # Check for triangles
        for triangle in itertools.combinations(G.nodes(), 3):
            if G.has_edge(triangle[0], triangle[1]) and \
               G.has_edge(triangle[1], triangle[2]) and \
               G.has_edge(triangle[0], triangle[2]):
                return False, "Triangle found"
    except nx.NetworkXNoCycle:
        pass

    # Check degrees
    for v in range(num_vertices):
        deg = G.degree(v)
        if not (2 <= deg <= 5):
            return False, f"Vertex {v} has degree {deg}"

    # Check fixed edges
    fixed_edges = {(2, 12), (3, 10), (6, 9), (3, 13), (3, 12), (0, 13)}
    for edge in fixed_edges:
        if not G.has_edge(edge[0], edge[1]):
            return False, f"Fixed edge {edge} missing"

    return True, "Valid"

